// ─── File: LastItemDemo.java ───
// Runnable demo of the concurrency-control progression for the LAST unit.
package com.bank.lastitem;

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.*;

public class LastItemDemo {

    private static final Logger log = Logger.getLogger("LastItem");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        int buyers = 50;

        // Rung 1: in-JVM AtomicInteger CAS
        InJvmStock inJvm = new InJvmStock(1);
        log.info(() -> "RUNG 1 in-JVM winners = " + raceBuyers(buyers, inJvm::tryClaim));

        // Rung 2: DB conditional atomic decrement (shared across instances)
        DbStock db = new DbStock(1);
        log.info(() -> "RUNG 2 DB winners = " + raceBuyers(buyers, db::tryClaim));

        // Rung 3: Redis SETNX + TTL distributed lock
        RedisLock redis = new RedisLock();
        AtomicInteger couponWinners = new AtomicInteger();
        raceBuyers(buyers, () -> {
            if (redis.tryClaimCoupon("DIWALI-LAST")) { couponWinners.incrementAndGet(); return true; }
            return false;
        });
        log.info(() -> "RUNG 3 Redis coupon winners = " + couponWinners.get());

        // Rung 4: single-consumer queue (no locks)
        QueueStock queue = new QueueStock(1);
        int qWinners = queue.run(buyers);
        log.info(() -> "RUNG 4 queue winners = " + qWinners);
    }

    // Fire N concurrent buyers; count how many successfully claimed.
    static int raceBuyers(int n, Callable<Boolean> claim) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(16);
        CountDownLatch gate = new CountDownLatch(1);
        AtomicInteger winners = new AtomicInteger();
        for (int i = 0; i < n; i++) {
            pool.submit(() -> {
                gate.await();
                if (Boolean.TRUE.equals(claim.call())) winners.incrementAndGet();
                return null;
            });
        }
        gate.countDown();
        pool.shutdown();
        pool.awaitTermination(2, TimeUnit.SECONDS);
        return winners.get();
    }
}

// ─── injvm/InJvmStock.java (single JVM only) ───
class InJvmStock {
    private final AtomicInteger stock;
    InJvmStock(int initial) { this.stock = new AtomicInteger(initial); }
    // Atomic CAS: take the last unit only if it is still available.
    boolean tryClaim() {
        int cur;
        do {
            cur = stock.get();
            if (cur <= 0) return false;
        } while (!stock.compareAndSet(cur, cur - 1));
        return true;
    }
}

// ─── db/DbStock.java (conditional atomic update, works across instances) ───
class DbStock {
    // Simulates: UPDATE stock SET qty=qty-1 WHERE id=? AND qty>0
    private int qty;
    DbStock(int qty) { this.qty = qty; }
    synchronized boolean tryClaim() {   // synchronized simulates the DB row lock
        if (qty > 0) { qty--; return true; }  // affected 1 row
        return false;                         // affected 0 rows → rejected
    }
}

// ─── redis/RedisLock.java (SETNX + TTL across instances) ───
class RedisLock {
    private final ConcurrentHashMap<String, Long> locks = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Boolean> redeemed = new ConcurrentHashMap<>();
    private static final long TTL_MS = 5000;
    // SET key NX PX ttl → only first caller wins the lock.
    boolean tryClaimCoupon(String couponId) {
        long now = System.currentTimeMillis();
        Long prev = locks.putIfAbsent(couponId, now + TTL_MS);
        boolean gotLock = (prev == null) || prev < now; // expired lock reclaimable
        if (!gotLock) return false;
        try {
            // critical section: redeem exactly once
            return redeemed.putIfAbsent(couponId, Boolean.TRUE) == null;
        } finally {
            locks.remove(couponId);   // release (check-token elided for brevity)
        }
    }
}

// ─── queue/QueueStock.java (serialize to one consumer, no locks) ───
class QueueStock {
    private int qty;
    QueueStock(int qty) { this.qty = qty; }
    // All requests go on a queue; ONE consumer processes them in order.
    int run(int buyers) throws InterruptedException {
        BlockingQueue<Integer> requests = new LinkedBlockingQueue<>();
        for (int i = 0; i < buyers; i++) requests.offer(i);
        int winners = 0;
        // single consumer — no contention, no locks needed
        while (!requests.isEmpty()) {
            requests.take();
            if (qty > 0) { qty--; winners++; }
        }
        return winners;
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
